def count_beautiful_integers(low: int, high: int, k: int) -> int:
    def digit_dp(num):
        s = str(num)
        n = len(s)

        # memoization table: (pos, tight, even_count, odd_count, remainder)
        memo = {}

        def dp(pos, tight, even, odd, rem):
            if pos == n:
                return 1 if even == odd and rem == 0 else 0

            key = (pos, tight, even, odd, rem)
            if key in memo:
                return memo[key]

            limit = int(s[pos]) if tight else 9
            total = 0

            for digit in range(0, limit + 1):
                new_tight = tight and (digit == limit)
                if digit % 2 == 0:
                    new_even = even + 1
                    new_odd = odd
                else:
                    new_even = even
                    new_odd = odd + 1
                new_rem = (rem * 10 + digit) % k
                total += dp(pos + 1, new_tight, new_even, new_odd, new_rem)

            memo[key] = total
            return total

        return dp(0, True, 0, 0, 0)

    # Calculate the count from 0 to high and subtract the count from 0 to low-1
    return digit_dp(high) - digit_dp(low - 1)
