def solve_grid(n: int, r: str, c: str) -> Optional[List[str]]:
    # Check if the counts of each character in r and c are compatible
    for char in 'ABC':
        if r.count(char) != c.count(char):
            return None

    # Initialize the grid with empty cells
    grid = [['.' for _ in range(n)] for _ in range(n)]

    # Fill in the leftmost characters according to r
    for i in range(n):
        grid[i][0] = r[i]

    # Fill in the topmost characters according to c
    for j in range(n):
        grid[0][j] = c[j]

    # Check for conflicts in the top-left corner
    if grid[0][0] != r[0] or grid[0][0] != c[0]:
        return None

    # We'll use backtracking to fill the rest of the grid
    # Create a list of positions to fill (excluding the first row and column)
    positions = []
    for i in range(n):
        for j in range(n):
            if i > 0 and j > 0:
                positions.append((i, j))

    # Create a list of characters to place
    chars = ['A', 'B', 'C']

    # Define a recursive function to try filling the grid
    def backtrack(pos):
        if pos == len(positions):
            return True

        i, j = positions[pos]

        # Determine which characters can be placed at (i, j)
        used_in_row = set(grid[i])
        used_in_col = set(grid[k][j] for k in range(n))
        possible_chars = [c for c in chars if c not in used_in_row and c not in used_col]

        for char in possible_chars:
            grid[i][j] = char
            if backtrack(pos + 1):
                return True
            grid[i][j] = '.'

        return False

    # Start the backtracking
    if backtrack(0):
        # Convert the grid to a list of strings
        return [''.join(row) for row in grid]
    else:
        return None
